"""Phase 2: Convert tool. Real Chromium; outputs verified by PIL (independent decoder), not by the app."""
from common import *
from playwright.sync_api import sync_playwright
PORT = 4195; BASE = f'http://127.0.0.1:{PORT}'; srv = start_server(PORT)
def setcolor(p, hexv): p.eval_on_selector('#bgcolor', "(el,v)=>{el.value=v;el.dispatchEvent(new Event('input',{bubbles:true}))}", hexv); ready(p)
def pick(p, label): p.click(f'.seg button:text-is("{label}")'); ready(p)
try:
  with sync_playwright() as pw:
    b = pw.chromium.launch(); ctx = b.new_context(viewport={'width': 1200, 'height': 900}, accept_downloads=True); p = ctx.new_page()
    errors = []; p.on('console', lambda m: errors.append(m.text) if m.type == 'error' else None); p.on('pageerror', lambda e: errors.append(str(e)))
    p.goto(BASE + '/'); check('Convert is in the nav and on the home cards', 'Convert' in p.locator('#toolNav a').all_text_contents() and p.locator('.task-card').filter(has=p.locator('text="Convert"')).count() == 1)
    load(p, BASE, 'alpha.png', '/convert')
    check('shows ORIGINAL format, size and transparency', 'PNG' in p.inner_text('.convert-from') and '800 × 600' in p.inner_text('.convert-from') and 'transparency channel' in p.inner_text('.convert-from'))
    check('original size shown', txt(p, 'sizeBefore').endswith('KB') or txt(p, 'sizeBefore').endswith('B'))
    pick(p, 'JPG'); f, name = download(p, 'a2j'); im = Image.open(f)
    check('PNG -> JPG: file really is JPEG (PIL), correct extension + name', im.format == 'JPEG' and name == 'alpha-converted.jpg', f'{im.format} {name}')
    check('dimensions preserved 800 × 600', im.size == (800, 600))
    rgb = im.convert('RGB'); check('transparent corners flattened to WHITE by default (not black)', near(rgb.getpixel((5, 5)), WHITE, 6), str(rgb.getpixel((5, 5))))
    check('subject kept (red circle)', near(rgb.getpixel((400, 300)), (220, 30, 30), 25))
    check('background picker visible for JPG + transparent source', p.locator('#bgcolor').is_visible())
    setcolor(p, '#00ff00'); f, _ = download(p, 'a2jg'); rgb = Image.open(f).convert('RGB')
    check('chosen background colour (#00ff00) used for transparent areas', near(rgb.getpixel((5, 5)), GREEN, 14) and near(rgb.getpixel((795, 595)), GREEN, 14), str(rgb.getpixel((5, 5))))
    check('result explains the flattening and colour', '#00ff00' in notices(p) and 'cannot store transparency' in notices(p), notices(p))
    check('tool reports what was actually produced', 'PNG → JPG (image/jpeg)' in p.inner_text('.convert-to') and '.jpg' in p.inner_text('.convert-to'), p.inner_text('.convert-to'))
    check('Format cell shows PNG → JPG', txt(p, 'statFormat') == 'PNG → JPG')
    pick(p, 'WEBP'); f, name = download(p, 'a2w'); im = Image.open(f)
    check('PNG -> WEBP: really WEBP, .webp, 800 × 600', im.format == 'WEBP' and name.endswith('.webp') and im.size == (800, 600), f'{im.format} {name}')
    check('WEBP keeps transparency (corner alpha 0)', im.convert('RGBA').getpixel((5, 5))[3] == 0)
    check('background picker hidden when output keeps transparency', not p.locator('#bgcolor').is_visible())
    pick(p, 'PNG'); f, name = download(p, 'a2p'); im = Image.open(f)
    check('PNG -> PNG same-format note + lossless pixels', im.format == 'PNG' and 'Same format' in p.inner_text('.tool-hint:not([role])') and im.convert('RGBA').getpixel((400, 300)) == (220, 30, 30, 255))

    load(p, BASE, 'alpha.webp', '/convert'); check('WEBP source detected with transparency', 'WEBP' in p.inner_text('.convert-from') and 'transparency channel' in p.inner_text('.convert-from'))
    pick(p, 'PNG'); f, name = download(p, 'w2p'); im = Image.open(f)
    check('WEBP -> PNG: PNG, alpha kept, pixel-exact subject', im.format == 'PNG' and im.convert('RGBA').getpixel((5, 5))[3] == 0 and im.convert('RGBA').getpixel((400, 300)) == (220, 30, 30, 255))
    pick(p, 'JPG'); f, _ = download(p, 'w2j'); check('WEBP -> JPG flattens to white', near(Image.open(f).convert('RGB').getpixel((5, 5)), WHITE, 6))

    load(p, BASE, 'photo.jpg', '/convert'); check('opaque JPEG source: says no transparency', 'no transparency' in p.inner_text('.convert-from'))
    pick(p, 'PNG'); f, name = download(p, 'j2p'); im = Image.open(f)
    check('JPG -> PNG keeps 3000 × 2000, real PNG', im.format == 'PNG' and im.size == (3000, 2000) and name == 'photo-converted.png', f'{im.format} {im.size} {name}')
    check('PNG output flags it is bigger (no false "smaller" claim)', 'no reduction' in p.inner_text('[data-r=barSaved]') or 'smaller' in p.inner_text('[data-r=barSaved]'))
    check('background picker hidden for opaque source', not p.locator('#bgcolor').is_visible())
    pick(p, 'WEBP'); f, _ = download(p, 'j2w'); im = Image.open(f); check('JPG -> WEBP: real WEBP, dims preserved', im.format == 'WEBP' and im.size == (3000, 2000))
    nav(p, 'Resize'); p.click('.chip:text-is("50%")'); ready(p); nav(p, 'Convert'); pick(p, 'JPG'); f, _ = download(p, 'rs')
    check('conversion honours a resize edit (1500 × 1000 JPEG)', Image.open(f).format == 'JPEG' and Image.open(f).size == (1500, 1000), str(Image.open(f).size))

    load(p, BASE, 'rotated.jpg', '/convert'); pick(p, 'PNG'); f, _ = download(p, 'rot'); im = Image.open(f).convert('RGB')
    check('EXIF-rotated JPG -> PNG is upright 1500 × 2000 (red top)', im.size == (1500, 2000) and near(im.getpixel((750, 100)), RED, 6) and near(im.getpixel((750, 1800)), BLUE, 6), str(im.size))
    load(p, BASE, 'pal_trns.png', '/convert'); check('palette PNG with tRNS detected as transparent', 'transparency channel' in p.inner_text('.convert-from'))
    load(p, BASE, 'alpha.png', '/compress'); p.select_option('#format', 'image/jpeg'); ready(p)
    check('flatten note also appears from the Compress tool', 'transparent areas were filled' in notices(p), notices(p))
    check('no console errors', not errors, ' | '.join(errors)[:200])
    ctx.close()

    # SIM: browser with no WEBP encoder (returns PNG)
    SIM1 = "const t2=HTMLCanvasElement.prototype.toBlob; HTMLCanvasElement.prototype.toBlob=function(cb,type,q){ if(type==='image/webp') type='image/png'; return t2.call(this,cb,type,q)};"
    c = b.new_context(accept_downloads=True); c.add_init_script(SIM1); p = c.new_page(); load(p, BASE, 'photo.jpg', '/convert'); p.wait_for_timeout(500)
    check('SIM no-WEBP browser: WEBP option disabled with explanation', p.is_disabled('.seg button:text-is("WEBP")') and 'WEBP output is not available' in p.inner_text('.tool-hint[role=status]'), p.inner_text('.tool-row'))
    check('SIM: JPG and PNG remain available', p.is_enabled('.seg button:text-is("JPG")') and p.is_enabled('.seg button:text-is("PNG")')); c.close()
    # SIM: browser that LABELS output webp but emits PNG bytes only for real images (1x1 probe is honest)
    SIM2 = "const t3=HTMLCanvasElement.prototype.toBlob; HTMLCanvasElement.prototype.toBlob=function(cb,type,q){ if(type==='image/webp'&&this.width>1){ return t3.call(this,(b)=>cb(new Blob([b],{type:'image/webp'})),'image/png',q)} return t3.call(this,cb,type,q)};"
    c = b.new_context(accept_downloads=True); c.add_init_script(SIM2); p = c.new_page(); load(p, BASE, 'photo.jpg', '/convert'); p.wait_for_timeout(300)
    p.click('.seg button:text-is("WEBP")'); ready(p); p.wait_for_timeout(500)
    check('SIM mislabelled output: never claims WEBP was produced', 'WEBP' not in p.inner_text('.convert-to') or 'not supported' in notices(p), p.inner_text('.convert-to') + ' | ' + notices(p))
    check('SIM mislabelled output: user told, falls back to a real JPG', 'not supported by this browser' in notices(p) and p.locator('[aria-label="Output format"] button[aria-pressed=true]').inner_text() == 'JPG', notices(p))
    f, name = download(p, 'sim2'); check('SIM: downloaded file matches the format shown (JPEG)', Image.open(f).format == 'JPEG' and name.endswith('.jpg'), name); c.close()
    b.close()
finally: srv.terminate()
finish()
